// MIT. Original ClinicalTrials receiving actions on the maintained Research transport.
import {need,object} from '../node/store.mjs';
const id=(value,pattern=/^[A-Za-z0-9][A-Za-z0-9._:-]{0,159}$/)=>{
 need(typeof value==='string'&&pattern.test(value),'CLINICALTRIALS_CLIENT_ID_INVALID');return encodeURIComponent(value);
};
const query=values=>{const params=new URLSearchParams();for(const[key,value]of Object.entries(values??{}))if(value!==undefined&&value!==null)params.set(key,String(value));return params.size?'?'+params:'';};
const root=dossierId=>'/api/dossiers/'+id(dossierId,/^d_[a-f0-9-]{36}$/)+'/clinical-trials/';
const operation=(dossierId,operationId)=>root(dossierId)+'operations/'+id(operationId,/^ct_[a-f0-9]{64}$/);
const retained=(dossierId,editionId)=>root(dossierId)+'retained/'+id(editionId,/^e_[a-f0-9]{64}$/);
function paging(options={},maximum=200){
 need(object(options)&&Object.keys(options).every(key=>['offset','limit'].includes(key)),'CLINICALTRIALS_REVIEW_PAGE_INVALID');
 const{offset=0,limit=50}=options;need(Number.isSafeInteger(offset)&&offset>=0&&Number.isSafeInteger(limit)&&limit>0&&limit<=maximum,'CLINICALTRIALS_REVIEW_PAGE_INVALID');return{offset,limit};
}
function inventory(options={}){
 need(object(options)&&Object.keys(options).every(key=>['after','limit'].includes(key)),'CLINICALTRIALS_OPERATION_PAGE_INVALID');
 const{after,limit=30}=options;need(after===undefined||typeof after==='string','CLINICALTRIALS_OPERATION_PAGE_INVALID');
 need(Number.isSafeInteger(limit)&&limit>0&&limit<=100,'CLINICALTRIALS_OPERATION_PAGE_INVALID');return{after,limit};
}
function analysisOptions(options={}){
 need(object(options)&&Object.keys(options).every(key=>['criteria','offset','limit'].includes(key)),'CLINICALTRIALS_ANALYSIS_FILTER_INVALID');
 const {criteria={},...page}=options;need(object(criteria),'CLINICALTRIALS_ANALYSIS_FILTER_INVALID');
 const selected=JSON.stringify(criteria);need(selected.length<=16384,'CLINICALTRIALS_ANALYSIS_FILTER_INVALID');return{...paging(page),criteria:selected};
}
function analysisExportOptions(options={}){
 need(object(options),'CLINICALTRIALS_ANALYSIS_FILTER_INVALID');
 const{format='csv',criteria={},...file}=options;need(['csv','json','html','md'].includes(format),'CLINICALTRIALS_ANALYSIS_FORMAT_INVALID');
 return{format,criteria:analysisOptions({criteria}).criteria,file};
}
function index(value){need(Number.isSafeInteger(value)&&value>=0,'CLINICALTRIALS_STUDY_INDEX_INVALID');return value;}
export function createClinicalTrialsClient({request,download,upload}){
 need([request,download,upload].every(value=>typeof value==='function'),'ORIGINAL_RESEARCH_CLIENT_REQUIRED');
 const file=(route,{file,...options}={})=>{need(typeof file==='string'&&file.length>0,'RESEARCH_OUTPUT_FILE_REQUIRED');return download(route,file,options);};
 return Object.freeze({
  inputs:(dossierId,options={})=>request(root(dossierId)+'inputs'+query(inventory(options))),
  input:(dossierId,sourceId)=>request(root(dossierId)+'inputs/'+id(sourceId,/^ctsrc_[a-f0-9]{64}$/)),
  importPacket:(dossierId,options)=>upload(root(dossierId)+'inputs',options),
  prepare:(dossierId,input)=>request(root(dossierId)+'prepare',input),
  operations:(dossierId,options={})=>request(root(dossierId)+'operations'+query(inventory(options))),
  review:(dossierId,operationId,options={})=>request(operation(dossierId,operationId)+query(paging(options))),
  start:(dossierId,operationId,{expectedPlanSha256}={})=>request(operation(dossierId,operationId)+'/start',{expectedPlanSha256}),
  stop:(dossierId,operationId)=>request(operation(dossierId,operationId)+'/stop',{}),
  receive:(dossierId,operationId,input)=>request(operation(dossierId,operationId)+'/receive?projection=metadata',input),
  record:(dossierId,operationId,at)=>request(operation(dossierId,operationId)+'/record'+query({index:index(at)})),
  compare:(dossierId,operationId,beforeOperationId)=>request(operation(dossierId,operationId)+'/compare'+query({before:id(beforeOperationId,/^ct_[a-f0-9]{64}$/)})),
  retained:(dossierId)=>request(root(dossierId)+'retained'),
  retainedReview:(dossierId,editionId,options={})=>request(retained(dossierId,editionId)+query(paging(options))),
  retainedRecord:(dossierId,editionId,at)=>request(retained(dossierId,editionId)+'/record'+query({index:index(at)})),
  compareRetained:(dossierId,beforeEditionId,afterEditionId)=>request(root(dossierId)+'retained/compare'+query({before:id(beforeEditionId,/^e_[a-f0-9]{64}$/),after:id(afterEditionId,/^e_[a-f0-9]{64}$/)})),
  analysis:(dossierId,operationId,options={})=>request(operation(dossierId,operationId)+'/analysis'+query(analysisOptions(options))),
  retainedAnalysis:(dossierId,editionId,options={})=>request(retained(dossierId,editionId)+'/analysis'+query(analysisOptions(options))),
  exportAnalysis:(dossierId,operationId,options={})=>{const selected=analysisExportOptions(options);return file(operation(dossierId,operationId)+'/analysis/'+selected.format+query({criteria:selected.criteria}),selected.file);},
  exportRetainedAnalysis:(dossierId,editionId,options={})=>{const selected=analysisExportOptions(options);return file(retained(dossierId,editionId)+'/analysis/'+selected.format+query({criteria:selected.criteria}),selected.file);},
  exportEdition:(dossierId,operationId,options)=>file(operation(dossierId,operationId)+'/edition',options),
  exportInputPacket:(dossierId,sourceId,options)=>file(root(dossierId)+'inputs/'+id(sourceId,/^ctsrc_[a-f0-9]{64}$/)+'/packet',options),
  exportRetainedEdition:(dossierId,editionId,options)=>file(retained(dossierId,editionId)+'/edition',options),
  exportRetainedPacket:(dossierId,editionId,options)=>file(retained(dossierId,editionId)+'/packet',options),
 });
}

// MIT. Retain an original ClinicalTrials source packet; use the standard Python ZIP reader.
// This module never calls the registry or acquires the original provider workspace lease.
import {createHash,randomUUID} from 'node:crypto';
import {open,link,unlink,mkdtemp,rm,readdir,stat} from 'node:fs/promises';
import {join,resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawn} from 'node:child_process';
import {Readable} from 'node:stream';
import {privateDirectory,readBytes,readJson,writeJson,safeCode as nativeCode} from '../node/store.mjs';
import {withPrivateLock} from '../../sf30-seller-sdk/routescan/quota.mjs';
import {need,object,sha,json,validateEdition} from './clinical-trials-model.mjs';
const MAX_PACKET=128*1024*1024,MAX_EDITION=64*1024*1024;
const SCRIPT=fileURLToPath(new URL('./clinical-trials-packet.py',import.meta.url));
const code=error=>nativeCode(error?.code,'CLINICALTRIALS_PACKET_READ_FAILED');
const sourceId=value=>{need(typeof value==='string'&&/^ctsrc_[a-f0-9]{64}$/.test(value),'CLINICALTRIALS_INPUT_ID_INVALID');return value;};
const digest=value=>{need(typeof value==='string'&&/^[a-f0-9]{64}$/.test(value),'CLINICALTRIALS_PACKET_SHA_REQUIRED');return value;};
async function sync(directory){const handle=await open(directory,'r');try{await handle.sync();}finally{await handle.close();}}
async function runReader(python,args,{signal}={}){
 signal?.throwIfAborted();
 const child=spawn(python,[SCRIPT,...args],{stdio:['ignore','pipe','pipe'],windowsHide:true});
 let out='',error='',spawnError=null;
 child.stdout.on('data',data=>{if(out.length<65536)out+=data.toString('utf8');});
 child.stderr.on('data',data=>{if(error.length<65536)error+=data.toString('utf8');});
 const abort=()=>child.kill('SIGTERM');signal?.addEventListener('abort',abort,{once:true});
 if(signal?.aborted)abort();
 const result=await new Promise(resolve=>{child.once('error',e=>{spawnError=e;});child.once('close',(exitCode,exitSignal)=>resolve({exitCode,exitSignal}));});
 signal?.removeEventListener('abort',abort);
 if(signal?.aborted)throw Object.assign(new Error('OPERATION_ABORTED'),{code:'OPERATION_ABORTED'});
 if(spawnError)throw Object.assign(new Error('CLINICALTRIALS_PYTHON_UNAVAILABLE'),{code:'CLINICALTRIALS_PYTHON_UNAVAILABLE'});
 if(result.exitCode!==0){
  let failure;try{failure=JSON.parse(error.trim().split('\n').at(-1));}catch{}
  const selected=/^CLINICALTRIALS_[A-Z0-9_]+$/.test(failure?.error??'')?failure.error:'CLINICALTRIALS_PACKET_READ_FAILED';
  throw Object.assign(new Error(selected),{code:selected});
 }
 let value;try{value=JSON.parse(out.trim());}catch{}
 need(value?.status==='CLINICALTRIALS_RETAINED_SOURCE_READ'&&/^[a-f0-9]{64}$/.test(value.sha256)&&
  Number.isSafeInteger(value.bytes)&&value.bytes>0&&value.bytes<=MAX_EDITION,'CLINICALTRIALS_READER_RESULT_INVALID');
 return value;
}
export async function openClinicalTrialsInputs({directory,python='python3'}={}){
 need(typeof python==='string'&&python.length>0&&!/[\u0000-\u001f]/.test(python),'CLINICALTRIALS_PYTHON_INVALID');
 directory=await privateDirectory(directory);const jobs=new Set(),work=new Set();let closed=false;
 const folder=id=>join(directory,sourceId(id));
 async function get(id){
  const value=await readJson(join(folder(id),'input.json'),8*1024*1024);
  need(value.schema==='stellar-forge.clinicaltrials-research-input.v1'&&value.sourceId===id&&
   value.packetSha256===id.slice(6)&&Array.isArray(value.captures),'CLINICALTRIALS_INPUT_CHANGED');
  return value;
 }
 async function importStreamCore(stream,{expectedSha256,expectedBytes=null,signal}={}){
  need(!closed,'CLINICALTRIALS_WORKSPACE_CLOSED');expectedSha256=digest(expectedSha256);
  need(expectedBytes===null||Number.isSafeInteger(expectedBytes)&&expectedBytes>0&&expectedBytes<=MAX_PACKET,'CLINICALTRIALS_PACKET_SIZE_INVALID');
  const id='ctsrc_'+expectedSha256,dir=await privateDirectory(folder(id));
  return withPrivateLock(dir,'input.lock',async()=>{
   const stage=await mkdtemp(join(dir,'.receiving-'));const temporary=join(stage,'packet.zip');
   let handle=null,published=false;
   try{
    handle=await open(temporary,'wx',0o600);const hasher=createHash('sha256');let count=0;
    for await(const piece of stream){
     signal?.throwIfAborted();const bytes=Buffer.from(piece);count+=bytes.length;
     need(count<=MAX_PACKET,'CLINICALTRIALS_PACKET_SIZE_INVALID');hasher.update(bytes);
     let at=0;while(at<bytes.length){const result=await handle.write(bytes,at,bytes.length-at);need(result.bytesWritten>0,'CLINICALTRIALS_SOURCE_WRITE_FAILED');at+=result.bytesWritten;}
    }
    need(count>0&&(expectedBytes===null||count===expectedBytes)&&hasher.digest('hex')===expectedSha256,'CLINICALTRIALS_PACKET_CHANGED');
    await handle.sync();await handle.close();handle=null;
    const output=join(stage,'inspection.json');
    const receipt=await runReader(python,['--input',temporary,'--expected-sha256',expectedSha256,'--output',output],{signal});
    const bytes=await readBytes(output,8*1024*1024);need(bytes.length===receipt.bytes&&sha(bytes)===receipt.sha256,'CLINICALTRIALS_READER_OUTPUT_CHANGED');
    const inspection=JSON.parse(bytes.toString('utf8'));
    need(inspection.packetSha256===expectedSha256&&inspection.packetBytes===count,'CLINICALTRIALS_INPUT_CHANGED');
    try{await link(temporary,join(dir,'packet.zip'));published=true;}catch(error){
     if(error.code!=='EEXIST')throw error;
     const existing=await readBytes(join(dir,'packet.zip'),MAX_PACKET);
     need(existing.length===count&&sha(existing)===expectedSha256,'CLINICALTRIALS_INPUT_CHANGED');published=true;
    }
    const value={...inspection,sourceId:id,receivedAt:new Date().toISOString()};
    try{
     const prior=await get(id);
     need(prior.packetSha256===expectedSha256&&prior.manifestSha256===inspection.manifestSha256,'CLINICALTRIALS_INPUT_CHANGED');
     await sync(dir);return prior;
    }catch(error){if(error.code!=='ENOENT')throw error;}
    await writeJson(join(dir,'input.json'),value,{exclusive:true});await sync(dir);return value;
   }finally{
    await handle?.close().catch(()=>{});
    // A committed source packet is never removed if metadata publication needs continuation.
    await rm(stage,{recursive:true,force:true});
   }
  });
 }
 async function importFile(path,options={}){
  need(typeof path==='string'&&path===resolve(path),'CLINICALTRIALS_ABSOLUTE_INPUT_REQUIRED');
  const handle=await open(path,'r');try{
   const before=await handle.stat();need(before.isFile()&&before.size<=MAX_PACKET,'CLINICALTRIALS_PACKET_SIZE_INVALID');
   const value=await managedImport(handle.createReadStream({autoClose:false}),{...options,expectedBytes:options.expectedBytes??before.size});
   const after=await handle.stat();need(before.dev===after.dev&&before.ino===after.ino&&before.size===after.size&&before.mtimeMs===after.mtimeMs&&before.ctimeMs===after.ctimeMs,'CLINICALTRIALS_PACKET_CHANGED');
   return value;
  }finally{await handle.close();}
 }
 async function list({after='',limit=30}={}){
  need(typeof after==='string'&&(after===''||/^ctsrc_[a-f0-9]{64}$/.test(after))&&Number.isSafeInteger(limit)&&limit>=1&&limit<=100,'CLINICALTRIALS_INPUT_PAGE_INVALID');
  const names=(await readdir(directory)).filter(x=>/^ctsrc_[a-f0-9]{64}$/.test(x)&&x>after).sort();
  const items=[];let last=after,more=false;
  for(const id of names){
   let item;try{item=await get(id);}catch(error){if(error.code==='ENOENT')continue;throw error;}
   if(items.length===limit){more=true;break;}items.push(item);last=id;
  }
  return {items,next:more?last:null};
 }
 async function buildCore(id,plan,{output,signal}={}){
  need(!closed,'CLINICALTRIALS_WORKSPACE_CLOSED');const input=await get(id);
  need(object(plan)&&plan.sourceId===id&&input.captures.some(row=>row.id===plan.captureId),'CLINICALTRIALS_CAPTURE_NOT_FOUND');
  const stage=await mkdtemp(join(folder(id),'.review-')),planPath=join(stage,'plan.json');
  const controller=new AbortController(),abort=()=>controller.abort();signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted)abort();
  jobs.add(controller);
  try{
   await writeJson(planPath,plan,{exclusive:true});
   const receipt=await runReader(python,['--input',join(folder(id),'packet.zip'),'--expected-sha256',input.packetSha256,
    '--plan',planPath,'--output',output],{signal:controller.signal});
   const bytes=await readBytes(output,MAX_EDITION);need(bytes.length===receipt.bytes&&sha(bytes)===receipt.sha256,'CLINICALTRIALS_READER_OUTPUT_CHANGED');
   const value=validateEdition(JSON.parse(bytes.toString('utf8')));
   need(value.sourcePacket.sha256===input.packetSha256&&value.sourcePacket.manifestSha256===input.manifestSha256&&
    value.usage.captureId===plan.captureId&&value.usage.sourceId===id&&value.usage.operationId===plan.operationId&&
    value.query===plan.question&&value.label===plan.label,'CLINICALTRIALS_EDITION_PLAN_CHANGED');
   return {bytes,value,sha256:receipt.sha256};
  }finally{signal?.removeEventListener('abort',abort);jobs.delete(controller);await rm(stage,{recursive:true,force:true});}
 }
 async function packet(id){
  const input=await get(id),bytes=await readBytes(join(folder(id),'packet.zip'),MAX_PACKET);
  need(bytes.length===input.packetBytes&&sha(bytes)===input.packetSha256,'CLINICALTRIALS_INPUT_CHANGED');
  return {bytes,sha256:input.packetSha256,filename:'clinicaltrials-workspace-'+input.packetSha256.slice(0,12)+'.zip'};
 }
 function tracked(fn,signal){
  need(!closed,'CLINICALTRIALS_WORKSPACE_CLOSED');
  const controller=new AbortController(),abort=()=>controller.abort();
  signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted)abort();
  const entry={controller,promise:null};
  const promise=(async()=>{controller.signal.throwIfAborted();return fn(controller.signal);})();
  entry.promise=promise;work.add(entry);
  promise.finally(()=>{work.delete(entry);signal?.removeEventListener('abort',abort);}).catch(()=>{});
  return promise;
 }
 const managedImport=(stream,options={})=>tracked(async signal=>{
  const abort=()=>stream.destroy?.(Object.assign(new Error('OPERATION_ABORTED'),{code:'OPERATION_ABORTED'}));
  signal.addEventListener('abort',abort,{once:true});if(signal.aborted)abort();
  try{return await importStreamCore(stream,{...options,signal});}
  finally{signal.removeEventListener('abort',abort);}
 },options.signal);
 const managedBuild=(id,plan,options={})=>tracked(signal=>buildCore(id,plan,{...options,signal}),options.signal);
 return {directory,python,identity:{schema:'stellar-forge.clinicaltrials-original-packet-reader.v1'},get,list,importStream:managedImport,importFile,build:managedBuild,packet,
  async close(){closed=true;for(const entry of work)entry.controller.abort();for(const controller of jobs)controller.abort();await Promise.allSettled([...work].map(entry=>entry.promise));}};
}

// MIT. Original ClinicalTrials packet → retained Research dossier interpretation.
// Full study content remains the original NDJSON text, including numeric tokens.
import {createHash} from 'node:crypto';
import {inflateRawSync} from 'node:zlib';
export const PROVIDER='clinicaltrials-gov',ORIGIN='https://clinicaltrials.gov';
export const PACKET='stellar-forge.clinicaltrials-packet.v1',ENVELOPE='sf88-research-results-v1';
export const BATCH_PACKET='stellar-forge.clinicaltrials-packet.v2';
const MAX_MANIFEST=16*1024*1024;
const packetSchema=value=>value===PACKET||value===BATCH_PACKET;
export const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
export const json=value=>Buffer.from(JSON.stringify(value,null,2)+'\n');
export const object=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
export function need(value,code){if(!value)throw Object.assign(new Error(code),{code});}
function ordered(value){
 if(Array.isArray(value))return value.map(ordered);
 if(object(value))return Object.fromEntries(Object.keys(value).sort().map(key=>[key,ordered(value[key])]));
 return value;
}
export const same=(left,right)=>JSON.stringify(ordered(left))===JSON.stringify(ordered(right));
function parse(bytes){try{return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}
 catch{need(false,'CLINICALTRIALS_RETAINED_JSON_INVALID');}}
// Read just the original Python ZIP's manifest for independent retained-source binding.
// Complete input validation (all declared files, paths and study/page equality) stays in
// clinical-trials-packet.py using Python's maintained zipfile implementation.
function manifestFromPacket(bytes){
 const fail='CLINICALTRIALS_PACKET_MANIFEST_CHANGED';
 const take=(offset,count)=>{need(Number.isSafeInteger(offset)&&offset>=0&&offset+count<=bytes.length,fail);return bytes.subarray(offset,offset+count);};
 const u16=offset=>take(offset,2).readUInt16LE(0),u32=offset=>take(offset,4).readUInt32LE(0);
 let end=-1;
 for(let offset=bytes.length-22;offset>=Math.max(0,bytes.length-65557);offset--)
  if(u32(offset)===0x06054b50&&offset+22+u16(offset+20)===bytes.length){end=offset;break;}
 need(end>=0&&u16(end+4)===0&&u16(end+6)===0&&u16(end+8)===u16(end+10),fail);
 const count=u16(end+10),centralSize=u32(end+12),central=u32(end+16);
 need(count>0&&count<=20001&&central+centralSize===end,fail);
 let offset=central,found=null;
 for(let index=0;index<count;index++){
  need(u32(offset)===0x02014b50,fail);
  const flags=u16(offset+8),method=u16(offset+10),compressed=u32(offset+20),size=u32(offset+24),
   nameLength=u16(offset+28),extraLength=u16(offset+30),commentLength=u16(offset+32),local=u32(offset+42);
  const name=take(offset+46,nameLength).toString('utf8');
  if(name==='manifest.json'){
   need(!found&&!(flags&1)&&[0,8].includes(method)&&size>0&&size<=MAX_MANIFEST&&local<central,fail);
   need(u32(local)===0x04034b50&&u16(local+8)===method,fail);
   const localName=u16(local+26),localExtra=u16(local+28);
   need(take(local+30,localName).toString('utf8')===name,fail);
   const start=local+30+localName+localExtra;
   need(start+compressed<=central,fail);
   const packed=take(start,compressed);
   found=method===0?Buffer.from(packed):inflateRawSync(packed,{maxOutputLength:MAX_MANIFEST});
   need(found.length===size,fail);
  }
  offset+=46+nameLength+extraLength+commentLength;need(offset<=end,fail);
 }
 need(offset===end&&found,fail);return {bytes:found,value:parse(found)};
}
export function packetBytes(value){
 need(object(value)&&packetSchema(value.schema)&&typeof value.base64==='string'&&
  Number.isSafeInteger(value.bytes)&&value.bytes>0&&value.bytes<=128*1024*1024,'CLINICALTRIALS_SOURCE_PACKET_REQUIRED');
 const bytes=Buffer.from(value.base64,'base64');
 need(bytes.toString('base64')===value.base64&&bytes.length===value.bytes&&sha(bytes)===value.sha256,'CLINICALTRIALS_SOURCE_PACKET_CHANGED');
 return bytes;
}
export function validateEdition(value){
 need(object(value)&&value.schema===ENVELOPE&&value.provider===PROVIDER&&value.success===true&&
  typeof value.query==='string'&&typeof value.label==='string'&&Array.isArray(value.results)&&
  Array.isArray(value.sourcePages)&&Array.isArray(value.sourceVersions)&&object(value.usage),
  'CLINICALTRIALS_RETAINED_EDITION_REQUIRED');
 const packet=packetBytes(value.sourcePacket),manifest=manifestFromPacket(packet);
 need(sha(manifest.bytes)===value.sourcePacket.manifestSha256&&manifest.value.schema===value.sourcePacket.schema&&
  Array.isArray(manifest.value.captures),'CLINICALTRIALS_ORIGINAL_MANIFEST_CHANGED');
 const batches=manifest.value.batches??[];
 need(Array.isArray(batches)&&(manifest.value.schema!==BATCH_PACKET||Array.isArray(manifest.value.batches))&&
  (!batches.length||manifest.value.schema===BATCH_PACKET),'CLINICALTRIALS_BATCH_PACKET_REQUIRED');
 const capture=manifest.value.captures.find(row=>row.id===value.usage.captureId);
 need(capture&&same(capture.configuration,value.usage.scope)&&capture.rowCount===value.results.length&&
  capture.pageCount===value.sourcePages.length&&capture.byteCount===value.usage.sourceBytes&&
  value.usage.occurrences===value.results.length&&
  value.usage.sourceId==='ctsrc_'+value.sourcePacket.sha256,'CLINICALTRIALS_CAPTURE_BINDING_CHANGED');
 need(value.sourceVersions.length===capture.versionRequests.length&&value.sourceVersions.every((row,index)=>same(row.request,capture.versionRequests[index])),
  'CLINICALTRIALS_ORIGINAL_VERSION_CHANGED');
 const complete=capture.status==='completed';
 need(value.usage.complete===complete&&value.status===(complete?'AVAILABLE':'PARTIAL')&&
  value.usage.coverage===(complete?'COMPLETE_CAPTURE':'PARTIAL_CAPTURE')&&
  value.usage.nextPageToken===capture.nextPageToken&&same(value.usage.sourceVersion,capture.version),
  'CLINICALTRIALS_CAPTURE_COVERAGE_CHANGED');
 const hash=createHash('sha256'),ids=new Set(),counts=Array(value.sourcePages.length).fill(0),pageHashes=value.sourcePages.map(()=>createHash('sha256'));let lastPage=-1;
 for(let index=0;index<value.sourcePages.length;index++){
  const page=value.sourcePages[index],original=capture.pages[index];
  need(page.index===index&&original&&Object.keys(page).every(key=>same(page[key],original[key]??null)),
   'CLINICALTRIALS_ORIGINAL_PAGE_CHANGED');
 }
 for(const result of value.results){
  need(object(result)&&typeof result.id==='string'&&/^NCT[0-9]{8}$/.test(result.id)&&
   typeof result.content==='string'&&result.content.endsWith('\n')&&object(result.metadata),
   'CLINICALTRIALS_WHOLE_STUDY_REQUIRED');
  const body=Buffer.from(result.content,'utf8'),meta=result.metadata,page=value.sourcePages[meta.pageIndex];
  need(body.length<=16*1024*1024&&body.length===meta.recordBytes&&sha(body)===meta.recordSha256&&
   meta.nctId===result.id&&meta.captureId===capture.id&&page&&meta.pageSha256===page.sha256&&
