      Number.isSafeInteger(source.bytes) && source.bytes > 0 &&
      typeof source.sha256 === 'string' && /^[0-9a-f]{64}$/.test(source.sha256),
      'CROSSREF_DOCUMENT_MANIFEST_SOURCE_INVALID');
