    if (typeof item === 'number') { need(Number.isFinite(item), code); return; }
    need((Array.isArray(item) || (object(item) && [Object.prototype, null].includes(Object.getPrototypeOf(item)))) && !seen.has(item), code);
    seen.add(item);
