      const payload={request,source:{...identity},question:question.text,dois,
        metadataRequests:dois.length,minimumUpdateRequests:request.includeUpdates?dois.length:0,
        maximumRequests:2000,sourceTerms:'https://www.crossref.org/documentation/retrieve-metadata/rest-api/'};
      const selected={schema:PLAN,id,preparedAt:now(),request,payload,sha256:digest(jsonBytes(payload))};
      await privateDirectory(join(path,'captures'));
      await writeJson(join(path,'plan.json'),selected,{exclusive:true});
      const current=await save(id,operationRecord(id));
      return {plan:selected,operation:current,running:false,interrupted:false,sourceMatches:true};
    });
  }
  async function collect(id,selected,controller,ready){
    return withPrivateLock(folder(id),'operation.lock',async()=>{
      let current=await state(id);
      if(['READY','IMPORTED'].includes(current.phase)){ready.resolve();return;}
      need(same(selected.payload.source,identity),'CROSSREF_SOURCE_CONFIGURATION_CHANGED');
      const retained=await references(id),byUrl=new Map(retained.map(row=>[row.capture.url,row]));
      current=await save(id,{...current,phase:'RUNNING',startedAt:current.startedAt??now(),error:null,responses:retained.length});
      ready.resolve();
      try{
        const resumed={
          async request(kind,input,options){
            const target=requestFor(kind,input),saved=byUrl.get(target.url);
            if(saved)return {capture:saved.capture,captureId:saved.ref.captureId,cached:true,resumed:true};
            return source.request(kind,input,options);
          }
        };
        const result=await collectCrossrefEdition({source:resumed,dois:selected.payload.dois,query:selected.payload.question,
          label:selected.request.label,includeUpdates:selected.request.includeUpdates,maxUpdatePages:selected.request.maxUpdatePages,
          refresh:selected.request.refresh,signal:controller.signal,
          async onCapture(receipt){
            const capture=await source.readCapture(receipt.captureId),url=capture.url;
            const ref={captureId:receipt.captureId,url,bodySha256:capture.bodySha256,status:capture.status,cached:receipt.cached,
              recordedAt:now(),request:capture.request};
            const existing=byUrl.get(url);
            if(existing)need(existing.ref.captureId===receipt.captureId,'CROSSREF_CAPTURE_REFERENCE_CHANGED');
            else{
              await writeJson(join(folder(id),'captures',digest(Buffer.from(url))+'.json'),ref,{exclusive:true});
              byUrl.set(url,{ref,capture});
            }
            current=await save(id,{...current,responses:byUrl.size,lastCapture:{captureId:ref.captureId,url,status:ref.status,cached:ref.cached}});
          }});
        validateCrossrefEdition(result.envelope);
        const bytes=jsonBytes(result.envelope);need(bytes.length<=LIMIT,'RESEARCH_RESPONSE_TOO_LARGE');
        const sha256=digest(bytes);
        try{await writeBytes(join(folder(id),'edition.json'),bytes,{exclusive:true});}
        catch(error){
          if(error.code!=='EEXIST')throw error;
          need(digest(await readBytes(join(folder(id),'edition.json'),LIMIT))===sha256,'CROSSREF_REVIEWED_EDITION_CHANGED');
        }
        current=await save(id,{...current,phase:'READY',error:null,editionSha256:sha256,editionBytes:bytes.length});
      }catch(error){
        current=await save(id,{...current,phase:controller.signal.aborted?'STOPPED':'FAILED',
          error:controller.signal.aborted?'CROSSREF_ACQUISITION_STOPPED':safeCode(error.code,'CROSSREF_ACQUISITION_FAILED')});
      }
    });
  }
  async function start(id,{expectedPlanSha256}={}){
    need(!closed,'CROSSREF_WORKSPACE_CLOSED');
    const selected=await plan(id);need(selected.sha256===expectedPlanSha256,'CROSSREF_PLAN_CHANGED');
    if(active.has(id))return inspect(id);
    const current=await state(id);
    if(['READY','IMPORTED'].includes(current.phase))return inspect(id);
    let accept,reject;
    const started=new Promise((resolve,rejectPromise)=>{accept=resolve;reject=rejectPromise;});
    const controller=new AbortController(),entry={controller,promise:null};active.set(id,entry);
    entry.promise=collect(id,selected,controller,{resolve:accept}).catch(error=>{reject(error);throw error;})
      .finally(()=>active.delete(id));
    entry.promise.catch(()=>{});
    await started;return inspect(id);
  }
  async function stop(id){
    await plan(id);
    const entry=active.get(id);
    if(entry){entry.controller.abort();await entry.promise;}
    else need(!await isRunning(id),'CROSSREF_OPERATION_RUNNING_ELSEWHERE');
    return inspect(id);
  }
  async function edition(id){
    const current=await state(id);
    need(['READY','IMPORTED'].includes(current.phase),'CROSSREF_EDITION_NOT_READY');
    const bytes=await readBytes(join(folder(id),'edition.json'),LIMIT);
    need(bytes.length===current.editionBytes&&digest(bytes)===current.editionSha256,'CROSSREF_REVIEWED_EDITION_CHANGED');
    return {bytes,value:validateCrossrefEdition(parseJson(bytes))};
  }
  async function review(id){
    const selected=await inspect(id),current=selected.operation;
    if(!['READY','IMPORTED'].includes(current.phase))return {...selected,currentRevision:null,questionMatches:null,review:null};
    const before=await dossiers.get(selected.plan.request.dossierId);
    const question=before.questions.find(row=>row.id===selected.plan.request.questionId);
    const {value}=await edition(id);
    const incoming=new Map(value.results.map(row=>[row.doi,row])),seen=new Set();
    const projected=before.sources.map(row=>{
      let doi;try{doi=requestFor('work',{doi:row.doi}).doi;}catch{return row;}
      seen.add(doi);return incoming.has(doi)?{...incoming.get(doi),id:row.id}:row;
    });
    projected.push(...value.results.filter(row=>!seen.has(row.doi)));
    const after={revision:before.revision,sources:projected};
    return {...selected,currentRevision:before.revision,questionMatches:question?.text===selected.plan.payload.question,
      review:{coverage:value.usage.coverage,usage:value.usage,warnings:value.warnings,
        comparison:compareCrossrefMetadata(before,after,{dois:selected.plan.payload.dois}),
        records:value.results.map(row=>({doi:row.doi,title:row.title,authors:row.authors,dates:row.metadata.dates,
          funders:row.metadata.crossref.funder??[],licenses:row.metadata.crossref.license??[],
          relations:row.metadata.crossref.relation??{},referenceCount:row.metadata.crossref['reference-count']??null,
          sourceOccurrences:row.metadata.sourceOccurrences}))}};
  }
  async function receive(id,{expectedRevision,expectedPlanSha256,expectedEditionSha256,projection='full'}={}){
    need(['full','metadata'].includes(projection),'RESEARCH_PROJECTION_INVALID');
    const receivedView=(dossierId,value)=>projection==='metadata'?value:fullView(dossierId,value);
    const path=folder(id);
    return withPrivateLock(path,'operation.lock',async()=>{
      const selected=await plan(id),current=await state(id);
      need(selected.sha256===expectedPlanSha256,'CROSSREF_PLAN_CHANGED');
      need(current.editionSha256===expectedEditionSha256,'CROSSREF_REVIEWED_EDITION_CHANGED');
      const before=await metadata(selected.request.dossierId);
      if(current.phase==='IMPORTED'){
        need(before.editions.some(row=>row.questionId===selected.request.questionId&&row.raw?.sha256===current.editionSha256),
          'CROSSREF_RECEIVED_EDITION_MISSING');
        return {operation:current,receipt:current.received,dossier:await receivedView(selected.request.dossierId,before)};
      }
      const pending=current.pendingReceive;
      const retained=before.editions.find(row=>row.questionId===selected.request.questionId&&row.raw?.sha256===current.editionSha256&&
        (row.origin?.operationId===id||pending?.duplicateEditionId===row.id));
      if(retained&&pending){
        revision(pending.expectedRevision);
        const duplicate=pending.duplicateEditionId===retained.id;
        const receivedRevision=pending.expectedRevision+(duplicate?0:1);
        const original=before.revision===receivedRevision?before:await metadata(selected.request.dossierId,{revision:receivedRevision});
        need(original.editions.some(row=>row.id===retained.id&&row.raw?.sha256===current.editionSha256&&
          (duplicate||row.origin?.operationId===id)),'CROSSREF_RECEIVE_RECONCILIATION_FAILED');
        const {value}=await edition(id);
        const receipt={dossierId:selected.request.dossierId,questionId:selected.request.questionId,
          originalRevision:pending.expectedRevision,revision:receivedRevision,duplicate,
          sourceSha256:current.editionSha256,coverage:value.usage.coverage,metadataRecords:value.results.length,
          receivedAt:pending.startedAt,reconciled:true};
        const saved=await save(id,{...current,phase:'IMPORTED',error:null,received:receipt,pendingReceive:null});
        return {operation:saved,receipt,dossier:await receivedView(selected.request.dossierId,before)};
      }
      need(before.revision===revision(expectedRevision),'REVISION_CONFLICT');
      const question=before.questions.find(row=>row.id===selected.request.questionId);
      need(question?.text===selected.payload.question,'CROSSREF_QUESTION_CHANGED');
      const {value}=await edition(id);
      const already=before.editions.find(row=>row.questionId===selected.request.questionId&&row.raw?.sha256===current.editionSha256);
      const pendingState=await save(id,{...current,pendingReceive:{expectedRevision,duplicateEditionId:already?.id??null,startedAt:now()}});
      const imported=await receiveCrossrefEdition(dossiers,selected.request.dossierId,{
        questionId:selected.request.questionId,label:selected.request.label,captures:value.originalResponses,
        dois:selected.payload.dois,expectedRevision,acquisition:value.usage.acquisition,
        sourceReference:selected.payload.sourceTerms,projection,
        origin:{mode:'CROSSREF_RESEARCH_WORKSPACE',operationId:id,planSha256:selected.sha256}});
      const receipt={dossierId:imported.dossierId,questionId:imported.questionId,originalRevision:imported.originalRevision,
        revision:imported.revision,duplicate:imported.duplicate,sourceSha256:imported.sourceSha256,coverage:imported.coverage,
        metadataRecords:imported.metadataRecords,receivedAt:now()};
      need(receipt.sourceSha256===current.editionSha256,'CROSSREF_RECEIVED_EDITION_CHANGED');
      const saved=await save(id,{...pendingState,phase:'IMPORTED',error:null,received:receipt,pendingReceive:null});
      return {operation:saved,receipt,dossier:imported.dossier};
    });
  }
  async function list(dossierId,{after='',limit=30}={}){
    need(typeof after==='string'&&(after===''||/^cr_[a-f0-9]{64}$/.test(after))&&Number.isSafeInteger(limit)&&limit>=1&&limit<=100,'CROSSREF_OPERATION_PAGE_INVALID');
    const names=(await readdir(operations)).filter(name=>/^cr_[a-f0-9]{64}$/.test(name)&&name>after).sort();
    const items=[];let last=after,more=false;
    for(const id of names){
      const selected=await plan(id);
      if(selected.request.dossierId!==dossierId)continue;
      if(items.length===limit){more=true;break;}
      items.push({plan:selected,operation:await state(id)});last=id;
    }
    return {items,next:more?last:null};
  }
  return {prepare,start,stop,inspect,review,receive,list,edition,
    async snapshot(){return {configured:true,identity:{...identity},source:await source.snapshot(),activeOperations:[...active.keys()]};},
    async close(){if(closed)return;closed=true;for(const entry of active.values())entry.controller.abort();
      await Promise.allSettled([...active.values()].map(entry=>entry.promise));}};
}

// MIT. DOI enrichment joins the original dossier's questions, revisions and retained evidence.
import {jsonBytes,parseJson,digest,need,object} from '../node/store.mjs';
import {buildCrossrefEdition,normalizeDoi,doiList,crossrefFieldChanges,parseCapture} from '../../sf30-seller-sdk/crossref/metadata.mjs';

export const CROSSREF_RECEIVING_CONTRACT='stellar-forge.crossref-dossier.v1';
function canonical(value){
  if(Array.isArray(value))return value.map(canonical);
  if(object(value))return Object.fromEntries(Object.keys(value).sort().map(key=>[key,canonical(value[key])]));
  return value;
}
export function validateCrossrefEdition(value){
  need(object(value)&&value.schema==='sf88-research-results-v1'&&value.provider==='crossref'&&
    value.usage?.schema==='stellar-forge.crossref-edition.v1'&&Array.isArray(value.originalResponses),'CROSSREF_EDITION_REQUIRED');
  const rebuilt=buildCrossrefEdition({captures:value.originalResponses,dois:value.usage.requestedDois,query:value.query,label:value.label,acquisition:value.usage.acquisition});
  need(JSON.stringify(canonical(value))===JSON.stringify(canonical(rebuilt)),'CROSSREF_EDITION_PROJECTION_CHANGED');
  return value;
}
export function selectedCrossrefDois(view,{questionId,selectedOnly=true}={}){
  need(object(view)&&Array.isArray(view.questions)&&Array.isArray(view.sources),'DOSSIER_VIEW_REQUIRED');
  need(view.questions.some(question=>question.id===questionId),'QUESTION_NOT_FOUND');
  const records=view.sources.filter(source=>(!selectedOnly||source.selected)&&source.doi&&
    source.citations?.some(citation=>citation.questionId===questionId));
  const values=[];
  for(const source of records){try{values.push(normalizeDoi(source.doi));}catch{/* Sources without a usable DOI stay in their original dossier. */}}
  need(values.length>0,'CROSSREF_SELECTED_DOIS_REQUIRED');return doiList(values);
}
export async function receiveCrossrefEdition(dossiers,id,{questionId,label='Crossref DOI enrichment',captures,dois,
  expectedRevision,sourceReference='',origin=null,acquisition,projection='full'}={}){
  need(Number.isSafeInteger(expectedRevision)&&expectedRevision>=0,'EXPECTED_REVISION_REQUIRED');
  need(['full','metadata'].includes(projection),'RESEARCH_PROJECTION_INVALID');
  const metadataAvailable=typeof dossiers.getMetadata==='function';
  const before=dois&&metadataAvailable?await dossiers.getMetadata(id):await dossiers.get(id);
  need(before.revision===expectedRevision,'REVISION_CONFLICT');
  const question=before.questions.find(question=>question.id===questionId);need(question,'QUESTION_NOT_FOUND');
  const selected=dois?doiList(dois):selectedCrossrefDois(before,{questionId});
  const envelope=buildCrossrefEdition({captures,dois:selected,query:question.text,label,acquisition});
  const raw=jsonBytes(envelope);need(raw.length<=64*1024*1024,'RESEARCH_RESPONSE_TOO_LARGE');
  const received=await dossiers.receive(id,{questionId,label,provider:'crossref',rawBytes:raw,sourceReference,
    expectedRevision,origin,...(metadataAvailable?{projection:'metadata'}:{})});
  const dossier=projection==='metadata'||Array.isArray(received.sources)?received:await dossiers.get(id,{revision:received.revision});
  return {schema:CROSSREF_RECEIVING_CONTRACT,dossierId:id,questionId,revision:dossier.revision,
    originalRevision:before.revision,duplicate:dossier.revision===before.revision,sourceSha256:digest(raw),
    requestedDois:selected,coverage:envelope.usage.coverage,metadataRecords:envelope.results.length,
    updateCollections:envelope.usage.updates,acquisition:envelope.usage.acquisition,dossier};
}
export async function receiveCrossrefBuyerResult(dossiers,id,{result,questionId,label='Crossref merchant result',
  expectedRevision,sourceReference='',intentId}={}){
  need(result&&typeof result.bytes==='function','ORIGINAL_BUYER_RESULT_REQUIRED');
  const raw=await result.bytes({limit:64*1024*1024});
  validateCrossrefEdition(parseJson(raw));
  // The original buyer receiver verifies its saved delivery and binds the original intent.
  return dossiers.receiveBuyerResult(id,{result,questionId,label,provider:'crossref',
    expectedRevision,sourceReference,intentId});
}
function crossrefRecord(source){
  const citations=(source?.citations??[]).filter(citation=>citation.provider==='crossref'&&object(citation.original?.metadata?.crossref));
  return citations.at(-1)?.original.metadata.crossref??(object(source?.metadata?.crossref)?source.metadata.crossref:null);
}
export function compareCrossrefMetadata(before,after,{dois}={}){
  const selected=dois?new Set(doiList(dois)):null;
  const records=view=>new Map((view.sources??[]).filter(source=>source.doi).flatMap(source=>{
    let doi;try{doi=normalizeDoi(source.doi);}catch{return [];}
    const record=crossrefRecord(source);return record&&(!selected||selected.has(doi))?[[doi,{sourceId:source.id,record}]]:[];
  }));
  const left=records(before),right=records(after),added=[],removed=[],changed=[];
  for(const [doi,value] of right){
    const old=left.get(doi);
    if(!old)added.push({doi,sourceId:value.sourceId,record:value.record});
    else {const fields=crossrefFieldChanges(old.record,value.record);if(fields.length)changed.push({doi,sourceId:value.sourceId,fields});}
  }
  for(const [doi,value] of left)if(!right.has(doi))removed.push({doi,sourceId:value.sourceId});
  return {schema:'stellar-forge.crossref-metadata-comparison.v1',before:before.revision,after:after.revision,added,removed,changed};
}
/** Acquire one reviewed DOI scope. Capture observers may persist original progress; their failures remain caller failures. */
export async function collectCrossrefEdition({source,dois,query,label='Crossref DOI enrichment',
  includeUpdates=true,maxUpdatePages=1000,refresh=false,signal,onCapture}={}){
  need(source&&typeof source.request==='function','CROSSREF_SOURCE_REQUIRED');
  need(typeof includeUpdates==='boolean'&&typeof refresh==='boolean'&&(onCapture===undefined||typeof onCapture==='function'),'CROSSREF_ENRICH_OPTIONS_INVALID');
  need(Number.isSafeInteger(maxUpdatePages)&&maxUpdatePages>=1&&maxUpdatePages<=10000,'CROSSREF_UPDATE_PAGE_LIMIT_INVALID');
  dois=doiList(dois);
  const captures=[],receipts=[],errors=[];
  const acquisition={schema:'stellar-forge.crossref-acquisition.v1',metadata:true,updates:includeUpdates,failures:errors};
  let requests=0,capacityReached=false;
  function recordFailure(phase,kind,input,code){
    errors.push({phase,code,request:{kind,...input}});
  }
  async function obtain(kind,input){
    if(requests>=2000){
      if(!capacityReached)recordFailure('capacity',kind,input,'CROSSREF_ACQUISITION_REQUEST_LIMIT');
      capacityReached=true;return null;
    }
    requests++;
    let result;
    try{signal?.throwIfAborted();result=await source.request(kind,input,{signal,refresh});}
    catch(error){
      if(signal?.aborted)throw error;
      const code=typeof error.code==='string'&&/^[A-Z][A-Z0-9_]{0,100}$/.test(error.code)?error.code:'CROSSREF_SOURCE_UNAVAILABLE';
      recordFailure('transport',kind,input,code);return null;
    }
    captures.push(result.capture);
    const receipt={captureId:result.captureId,status:result.capture.status,
      request:result.capture.request,bodySha256:result.capture.bodySha256,cached:result.cached};
    receipts.push(receipt);
    // Progress observers are caller code; their failures are not provider transport failures.
    await onCapture?.(receipt);
    try{return parseCapture(result.capture);}catch{return null;}
  }
  for(const doi of dois){await obtain('work',{doi});if(capacityReached)break;}
  if(includeUpdates&&!capacityReached){
    for(const doi of dois){
      let cursor='*';const seen=new Set();
      for(let page=0;page<maxUpdatePages;page++){
        const input={doi,rows:1000,cursor};seen.add(cursor);
        const result=await obtain('updates',input);
        if(!result?.successful)break;
        if(result.value.message.items.length<1000)break;
        const next=result.value.message['next-cursor'];
        if(typeof next!=='string'||!next){recordFailure('pagination','updates',input,'CROSSREF_NEXT_CURSOR_MISSING');break;}
        if(seen.has(next)){recordFailure('pagination','updates',input,'CROSSREF_CURSOR_NOT_ADVANCING');break;}
        if(page+1===maxUpdatePages){recordFailure('capacity','updates',input,'CROSSREF_UPDATE_PAGE_LIMIT');break;}
        // Current Crossref cursors advance; every following request retains the same DOI filter and rows.
        cursor=next;
      }
      if(capacityReached)break;
    }
  }
  const envelope=buildCrossrefEdition({captures,dois,query,label,acquisition});
  return {envelope,captures,receipts,errors};
}
/** Original source caching retains progress if acquisition meets a revision conflict. */
export async function enrichCrossrefDossier(dossiers,id,{source,questionId,expectedRevision,selectedOnly=true,
  includeUpdates=true,label='Crossref DOI enrichment',maxUpdatePages=1000,refresh=false,signal,onCapture}={}){
  need(typeof selectedOnly==='boolean','CROSSREF_ENRICH_OPTIONS_INVALID');
  const before=await dossiers.get(id);need(before.revision===expectedRevision,'REVISION_CONFLICT');
  const question=before.questions.find(item=>item.id===questionId);need(question,'QUESTION_NOT_FOUND');
  const dois=selectedCrossrefDois(before,{questionId,selectedOnly});
  const collected=await collectCrossrefEdition({source,dois,query:question.text,label,includeUpdates,maxUpdatePages,refresh,signal,onCapture});
  const imported=await receiveCrossrefEdition(dossiers,id,{questionId,label,captures:collected.captures,dois,expectedRevision,
    acquisition:collected.envelope.usage.acquisition,
    sourceReference:'https://www.crossref.org/documentation/retrieve-metadata/rest-api/'});
  return {...imported,receipts:collected.receipts,errors:collected.errors,comparison:compareCrossrefMetadata(before,imported.dossier,{dois})};
}

