export const DOCUMENT_COMMANDS=Object.freeze(['documents-help',...Object.keys(commandOptions)]);

const usage="Research Documents and Pipelines\n\n  research-client COMMAND --connection-file /private/application-url.json --directory /original/dossier-store --id DOSSIER [OPTIONS]\n  research-dossiers remote COMMAND --connection-file /private/application-url.json --directory /original/dossier-store --id DOSSIER [OPTIONS]\n\nDocuments from completed original purchases or received editions:\n  documents-list [--after PURCHASE_ID --limit N]\n  documents-review --input SELECTION.json\n  documents-elements --input FILTER.json\n  documents-receive --input RECEIVING.json\n  documents-download --input DOWNLOAD.json --out NEW_FILE [--sha256 SHA256]\n\nSelection: {\"purchaseId\":\"u_...\"} or {\"editionId\":\"e_...\"}.\nFILTER: {\"selection\":SELECTION,\"expectedEditionSha256\":\"...\",\"offset\":0,\"limit\":30,\n         \"page\":\"\",\"type\":\"\",\"query\":\"\"}\nRECEIVING: {\"selection\":{\"purchaseId\":\"u_...\"},\"expectedEditionSha256\":\"...\",\n            \"questionId\":\"q_...\",\"label\":\"Original document\",\"expectedRevision\":N}\nDOWNLOAD: {\"selection\":SELECTION,\"expectedEditionSha256\":\"...\",\n           \"kind\":\"document|response|edition\"}\n\nPrepare and operate an original managed pipeline:\n  pipelines-list [--after OPERATION_ID --limit N]\n  pipelines-operation --operation OPERATION_ID\n  pipelines-prepare --input PREPARATION.json\n  pipelines-submit|pipelines-refresh|pipelines-cancel|pipelines-reconcile|pipelines-retain\n      --operation OPERATION_ID --input ACTION.json\n  pipelines-provider-jobs --operation OPERATION_ID [--input FILTER.json]\n\nPREPARATION:\n  {\"requestId\":\"original-request\",\"profileId\":\"configured-profile\",\"questionId\":\"q_...\",\n   \"label\":\"Original processing\",\"expectedRevision\":N,\n   \"files\":[{\"file\":\"source.pdf\",\"sha256\":\"...\",\n             \"filename\":\"source.pdf\",\"contentType\":\"application/pdf\"}]}\nRelative source paths are resolved against PREPARATION.json. All source files are\nverified before upload. The existing source limits and workspace upload cap apply.\n\nACTION uses the original OPERATION revision, including revision zero:\n  submit:    {\"requestId\":\"submit-1\",\"expectedRevision\":N,\"expectedPlanSha256\":\"...\"}\n  refresh:   {\"requestId\":\"observe-1\",\"expectedRevision\":N}\n  cancel:    {\"requestId\":\"cancel-1\",\"expectedRevision\":N,\"reason\":\"Operator decision\"}\n  reconcile: {\"requestId\":\"reconcile-1\",\"expectedRevision\":N,\"expectedPlanSha256\":\"...\",\n              \"providerJobId\":\"original-provider-job\",\"reason\":\"Matched original job\"}\n  retain:    {\"requestId\":\"retain-1\",\"expectedRevision\":N,\"fileId\":\"provider-file\",\"nodeId\":\"provider-node\"}\nProvider-job FILTER may contain workflowId and status.\n\nReview, receive and download original pipeline results:\n  pipelines-review --input SELECTION.json\n  pipelines-elements --input FILTER.json\n  pipelines-receive --input RECEIVING.json\n  pipelines-input|pipelines-output --operation OPERATION_ID --file-id ORIGINAL_FILE_ID\n      --out NEW_FILE [--sha256 SHA256]\n  pipelines-download --input DOWNLOAD.json --out NEW_FILE [--sha256 SHA256]\n\nPipeline SELECTION: {\"operationId\":\"up_...\",\"outputId\":\"out_...\"} or {\"editionId\":\"e_...\"}.\nFILTER has the same fields as the Documents filter.\nRECEIVING: {\"selection\":{\"operationId\":\"up_...\",\"outputId\":\"out_...\"},\n            \"requestId\":\"receive-1\",\"expectedEditionSha256\":\"...\",\"questionId\":\"q_...\",\n            \"label\":\"Received output\",\"expectedRevision\":N}\nDOWNLOAD: {\"selection\":SELECTION,\"expectedEditionSha256\":\"...\",\"kind\":\"output|edition\"}.\n\nPreparation and receiving use the DOSSIER revision. Submit/refresh/cancel/\nreconcile/retain use the saved OPERATION revision. Retention returns the out_...\nID used for review and receiving. A lost write reply stays with that original\nrequest and operation; read it before another action. Downloads write complete\noriginal bytes to a new file and return their size and digest on stdout.\n\nConnection files are private host files and are reread by the existing client.\n--timeout-ms N selects the existing client timeout. The full operating guide is\nRESEARCH_DOCUMENTS.md beside workspace-client.mjs.\n";

const selected=value=>Object.fromEntries(Object.entries(value).filter(([,item])=>item!==undefined));
const compact=value=>value?.dossier?{...value,dossier:researchSummary(value.dossier)}:value;
export async function main(argv=process.argv.slice(2),{output=process.stdout}={}){
  const [command,...args]=argv;
  if(command==='documents-help'||!command){output.write(usage);return;}
  need(Object.hasOwn(commandOptions,command),'COMMAND_UNKNOWN');
  const names=['connection-file','directory','timeout-ms','id',...commandOptions[command]];
  const {values,tokens}=parseArgs({args,options:Object.fromEntries(names.map(name=>[name,{type:'string'}])),
    strict:true,allowPositionals:false,tokens:true});
  const seen=new Set();
  for(const token of tokens)if(token.kind==='option'){
    need(!seen.has(token.name),'ARGUMENT_REPEATED');seen.add(token.name);
  }
  const required=name=>{need(typeof values[name]==='string'&&values[name].length>0,'ARGUMENT_REQUIRED');return values[name];};
  const number=name=>{
    if(values[name]===undefined)return undefined;
    need(/^(0|[1-9][0-9]{0,8})$/.test(values[name]),'INTEGER_ARGUMENT_REQUIRED');return Number(values[name]);
  };
  const digest=()=>{
    if(values.sha256===undefined)return undefined;
    need(/^[a-f0-9]{64}$/.test(values.sha256),'RESEARCH_SHA256_REQUIRED');return values.sha256;
  };
  const input=async()=>{
    const value=parseJson(await readResearchHostFile(resolve(required('input')),2*1024*1024));
    need(object(value),'REQUEST_OBJECT_REQUIRED');return value;
  };
  const id=required('id');
  const client=new ResearchWorkspaceClient({connectionFile:resolve(required('connection-file')),directory:resolve(required('directory'))},
    values['timeout-ms']===undefined?{}:{timeoutMs:number('timeout-ms')});
  try{
    await client.status();
    const documents=client.documents(),pipelines=client.pipelines();
    const page=selected({after:values.after,limit:number('limit')});
    const outputFile=()=>({file:resolve(required('out')),...selected({expectedSha256:digest()})});
    let result;
    switch(command){
      case 'documents-list':result=await documents.list(id,page);break;
      case 'documents-review':result=await documents.review(id,await input());break;
      case 'documents-elements':result=await documents.elements(id,await input());break;
      case 'documents-receive':result=await documents.receive(id,await input());break;
      case 'documents-download':{
        const request=await input();
        need(Object.keys(request).every(key=>['selection','expectedEditionSha256','kind'].includes(key)),
          'UNSTRUCTURED_DOWNLOAD_SELECTION_INVALID');
        result=await documents.download(id,{...request,...outputFile()});break;
      }
      case 'pipelines-list':result=await pipelines.list(id,page);break;
      case 'pipelines-operation':result=await pipelines.operation(id,required('operation'));break;
      case 'pipelines-prepare':{
        const request=await input();
        need(Array.isArray(request.files),'PIPELINE_INPUT_SELECTION_REQUIRED');
        const root=dirname(resolve(required('input')));
        request.files=request.files.map(item=>{
          need(object(item)&&typeof item.file==='string'&&item.file.length>0,'RESEARCH_ORIGINAL_FILE_REQUIRED');
          return {...item,file:resolve(root,item.file)};
        });
        result=await pipelines.prepareFiles(id,request);break;
      }
      case 'pipelines-submit':result=await pipelines.submit(id,required('operation'),await input());break;
      case 'pipelines-refresh':result=await pipelines.refresh(id,required('operation'),await input());break;
      case 'pipelines-cancel':result=await pipelines.cancel(id,required('operation'),await input());break;
      case 'pipelines-reconcile':result=await pipelines.reconcile(id,required('operation'),await input());break;
      case 'pipelines-retain':result=await pipelines.retainOutput(id,required('operation'),await input());break;
      case 'pipelines-provider-jobs':result=await pipelines.providerJobs(id,required('operation'),values.input?await input():{});break;
      case 'pipelines-review':result=await pipelines.review(id,await input());break;
      case 'pipelines-elements':result=await pipelines.elements(id,await input());break;
      case 'pipelines-receive':result=await pipelines.receive(id,await input());break;
      case 'pipelines-input':result=await pipelines.downloadInput(id,required('operation'),required('file-id'),outputFile());break;
      case 'pipelines-output':result=await pipelines.downloadOutput(id,required('operation'),required('file-id'),outputFile());break;
      case 'pipelines-download':{
        const request=await input();
        need(Object.keys(request).every(key=>['selection','expectedEditionSha256','kind'].includes(key)),
          'PIPELINE_DOWNLOAD_SELECTION_INVALID');
        result=await pipelines.downloadReceived(id,{...request,...outputFile()});break;
      }
    }
    result=compact(result);output.write(JSON.stringify(result,null,2)+'\n');return result;
  }finally{await client.close();}
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  main().catch(error=>{
    process.stderr.write(JSON.stringify({error:safeCode(error.code,'RESEARCH_DOCUMENT_COMMAND_FAILED'),
      ...(Number.isInteger(error.status)?{status:error.status}:{}),
      ...(error.destinationPublished?{destinationPublished:true,file:error.file}:{}),
      ...(error.sourceCleanupFailed?{sourceCleanupFailed:true}:{}),
      ...(error.outcomeUnknown?{outcomeUnknown:true,requestId:error.requestId,operationId:error.operationId,
        recovery:error.recovery??'Read the original saved request and operation before another action.'}:{})})+'\n');
    process.exitCode=1;
  });
}

// MIT. Complete Documents and managed Pipelines on the original Research HTTP client.
import {basename,resolve} from 'node:path';
import {Readable} from 'node:stream';
import {BuyerError,need,object} from '../node/store.mjs';
import {openResearchSource} from './workspace-files.mjs';

const pathId=value=>{
  need(typeof value==='string'&&value.length>0&&value.length<=160&&!/[\u0000-\u001f\u007f/\\]/.test(value),
    'RESEARCH_ID_INVALID');return encodeURIComponent(value);
};
const path=(id,family)=>'/api/dossiers/'+pathId(id)+'/'+family;
const query=value=>{
  const parameters=new URLSearchParams();
  for(const[key,item]of Object.entries(value??{}))if(item!==undefined&&item!==null)parameters.set(key,String(item));
  return parameters.size?'?'+parameters.toString():'';
};
const digest=value=>need(typeof value==='string'&&/^[a-f0-9]{64}$/.test(value),'RESEARCH_ORIGINAL_FILE_DIGEST_REQUIRED');
const text=(value,maximum)=>typeof value==='string'&&value.trim().length>0&&Buffer.byteLength(value)<=maximum&&
  !/[\u0000-\u001f\u007f]/.test(value);
const fields=(value,keys,code)=>{
  need(object(value)&&Object.keys(value).every(key=>keys.includes(key)),code);return value;
};
const select=(value,keys)=>Object.fromEntries(keys.filter(key=>value[key]!==undefined).map(key=>[key,value[key]]));
const operation=(id,operationId)=>{
  need(/^up_[a-f0-9]{64}$/.test(operationId??''),'PIPELINE_OPERATION_ID_INVALID');
  return path(id,'pipelines/operations/')+operationId;
};
const controls=['requestId','profileId','questionId','label','expectedRevision'];
const readonly={readOnly:true};

/** Uses the same retained purchase/edition readers as the Documents browser pane. */
export function createDocumentWorkspaceClient({request,downloadRequest}){
  return Object.freeze({
    list:(id,{after,limit,...options}={})=>request(path(id,'unstructured')+query({after,limit}),undefined,options),
    review:(id,selection,options={})=>request(path(id,'unstructured/review'),{selection},{...options,...readonly}),
    elements:(id,input,options={})=>request(path(id,'unstructured/elements'),input,{...options,...readonly}),
    receive:(id,input,options={})=>request(path(id,'unstructured/receive')+'?projection=metadata',input,options),
    download:(id,{selection,expectedEditionSha256,kind,file,...options}={})=>{
      need(['document','response','edition'].includes(kind),'UNSTRUCTURED_DOWNLOAD_SELECTION_INVALID');
      return downloadRequest(path(id,'unstructured/download'),file,
        {selection,expectedEditionSha256,file:kind},options);
    },
  });
}

/** Uses original saved operation IDs and native action request/revision contracts. */
export function createPipelineWorkspaceClient({request,download,downloadRequest,prepareFiles}){
  return Object.freeze({
    list:(id,{after,limit,...options}={})=>request(path(id,'pipelines')+query({after,limit}),undefined,options),
    operation:(id,operationId,options={})=>request(operation(id,operationId),undefined,options),
    prepareFiles:(id,input,options={})=>prepareFiles(id,input,options),
    submit:(id,operationId,input,options={})=>request(operation(id,operationId)+'/submit',input,options),
    refresh:(id,operationId,input,options={})=>request(operation(id,operationId)+'/refresh',input,options),
    cancel:(id,operationId,input,options={})=>request(operation(id,operationId)+'/cancel',input,options),
    providerJobs:(id,operationId,input={},options={})=>request(operation(id,operationId)+'/provider-jobs',input,{...options,...readonly}),
    reconcile:(id,operationId,input,options={})=>request(operation(id,operationId)+'/reconcile',input,options),
    retainOutput:(id,operationId,input,options={})=>request(operation(id,operationId)+'/retain',input,options),
    review:(id,selection,options={})=>request(path(id,'pipelines/review'),{selection},{...options,...readonly}),
    elements:(id,input,options={})=>request(path(id,'pipelines/elements'),input,{...options,...readonly}),
    receive:(id,input,options={})=>request(path(id,'pipelines/receive')+'?projection=metadata',input,options),
    downloadInput:(id,operationId,inputId,{file,...options}={})=>{
      need(/^in_[a-f0-9]{64}$/.test(inputId??''),'PIPELINE_INPUT_ID_INVALID');
      return download(operation(id,operationId)+'/inputs/'+inputId,file,options);
    },
    downloadOutput:(id,operationId,outputId,{file,...options}={})=>{
      need(/^out_[a-f0-9]{64}$/.test(outputId??''),'PIPELINE_OUTPUT_ID_INVALID');
      return download(operation(id,operationId)+'/outputs/'+outputId,file,options);
    },
    downloadReceived:(id,{selection,expectedEditionSha256,kind,file,...options}={})=>{
      need(['output','edition'].includes(kind),'PIPELINE_DOWNLOAD_SELECTION_INVALID');
      return downloadRequest(path(id,'pipelines/download'),file,
        {selection,expectedEditionSha256,file:kind},options);
    },
  });
}

/**
 * Verify all selected host files before sending. Stream canonical base64 from each
 * SAME verified descriptor into the existing JSON prepare route. The native file
 * reader checks its second complete digest and file stamp before the final JSON
 * suffix is emitted, so a changed source cannot become a complete prepare body.
 * The caller owns the original Research client pending-operation scope.
 */
export async function sendPipelineFiles({inspect,send},id,input,{signal}={}){
  fields(input,[...controls,'files'],'PIPELINE_PREPARATION_FIELDS_INVALID');
  need(text(input.requestId,256)&&text(input.profileId,128)&&text(input.questionId,160)&&text(input.label,240),
    'PIPELINE_PREPARATION_SELECTION_REQUIRED');
  need(Number.isSafeInteger(input.expectedRevision)&&input.expectedRevision>=1,'EXPECTED_REVISION_REQUIRED');
  need(Array.isArray(input.files)&&input.files.length>0&&input.files.length<=32,'PIPELINE_INPUT_SELECTION_REQUIRED');
  const sourceView=await inspect(path(id,'pipelines')+'?limit=1',{signal}),limits=sourceView.source?.limits;
  need(sourceView.configured===true&&object(limits),'PIPELINE_SOURCE_NOT_CONFIGURED');
  for(const key of ['maxInputs','maxInputBytes','maxTotalInputBytes'])
    need(Number.isSafeInteger(limits[key])&&limits[key]>0,'PIPELINE_SOURCE_LIMITS_INVALID');
  need(Number.isSafeInteger(sourceView.uploadLimitBytes)&&sourceView.uploadLimitBytes>0&&
    input.files.length<=limits.maxInputs,'PIPELINE_INPUT_SELECTION_REQUIRED');
  const maximum=Math.min(sourceView.uploadLimitBytes,limits.maxTotalInputBytes);
  const originals=[];let body,result,failure;
  try{
    let total=0;
    for(const item of input.files){
      fields(item,['file','sha256','filename','contentType'],'PIPELINE_INPUT_FIELDS_INVALID');
      need(typeof item.file==='string'&&item.file.length>0,'RESEARCH_ORIGINAL_FILE_REQUIRED');digest(item.sha256);
      const filename=item.filename??basename(item.file),contentType=item.contentType??'application/octet-stream';
      need(text(filename,1024)&&!/[\\/]/.test(filename)&&text(contentType,256),'PIPELINE_INPUT_METADATA_INVALID');
      const source=await openResearchSource(resolve(item.file),Math.min(maximum,limits.maxInputBytes),{sha256:item.sha256});
      originals.push({filename,contentType,source});
      total+=source.bytes;need(total<=maximum,'PIPELINE_UPLOAD_TOO_LARGE');
    }
    const metadata=JSON.stringify(select(input,controls));
    const start=metadata.slice(0,-1)+',"inputs":[',end=']}';
    const prefixes=originals.map((item,index)=>(index?',':'')+
      JSON.stringify({filename:item.filename,contentType:item.contentType}).slice(0,-1)+',"base64":"');
    const close='"}';
    const contentLength=Buffer.byteLength(start)+Buffer.byteLength(end)+
      originals.reduce((size,item,index)=>size+Buffer.byteLength(prefixes[index])+Math.ceil(item.source.bytes/3)*4+close.length,0);
    const payload=(async function*(){
      yield Buffer.from(start);
      for(let index=0;index<originals.length;index++){
        yield Buffer.from(prefixes[index]);let carry=Buffer.alloc(0);
        for await(const chunk of originals[index].source.stream){
          const bytes=carry.length?Buffer.concat([carry,chunk]):chunk;
          const boundary=bytes.length-bytes.length%3;
          if(boundary)yield Buffer.from(bytes.subarray(0,boundary).toString('base64'));
          carry=boundary===bytes.length?Buffer.alloc(0):Buffer.from(bytes.subarray(boundary));
        }
        if(carry.length)yield Buffer.from(carry.toString('base64'));
        yield Buffer.from(close);
      }
      yield Buffer.from(end);
    })();
    body=Readable.from(payload);
    result=await send(path(id,'pipelines/prepare'),{
      body,signal,headers:{'Content-Type':'application/json','Content-Length':String(contentLength)},
    });
    const received=result?.plan?.payload?.inputs;
    if(result?.plan?.payload?.request?.requestId!==input.requestId||!Array.isArray(received)||
      received.length!==originals.length||originals.some((item,index)=>received[index]?.filename!==item.filename||
        received[index]?.contentType!==item.contentType||received[index]?.bytes!==item.source.bytes||
        received[index]?.sha256!==item.source.sha256)){
      throw new BuyerError('PIPELINE_PREPARATION_SOURCE_CHANGED',{outcomeUnknown:true,
        requestId:input.requestId,operationId:result?.plan?.id,
        recovery:'Inspect the original saved pipeline request before preparing another operation.'});
    }
  }catch(error){
    failure=error;
    if(error.outcomeUnknown&&error.requestId===undefined)error.requestId=input.requestId;
  }finally{
    body?.destroy();
    const closed=await Promise.allSettled(originals.map(item=>item.source.close()));
    if(closed.some(item=>item.status==='rejected')){
      if(failure)failure.sourceCleanupFailed=true;
      else result={...result,clientWarnings:[...(result.clientWarnings??[]),
        {code:'RESEARCH_SOURCE_CLOSE_FAILED',requestId:input.requestId,operationId:result.plan?.id}]};
    }
  }
  if(failure)throw failure;
  return result;
}

// MIT — Research project state beside the original SF88 buyer.
import { readdir, mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { randomUUID } from 'node:crypto';
import {
  privateDirectory, writeJson, readJson, writeBytes, readBytes, digest, jsonBytes,
  need, object, BuyerError, safeCode,
} from '../node/store.mjs';
import { normalizeResponse, normalizeProjection, sourceView, compareViews } from './normalize.mjs';
import { markdownReport, htmlReport } from './report.mjs';
import { portableEntries, encodePortable } from './portable.mjs';
import {inspectSourceBundle} from './source-bundles.mjs';
import {CITATION_REVIEW_SCHEMA,citationDigest,citationUpdateModel,citationUpdatePage,citationReviewInput,
  recordCitationReview,validateCitationReviewState,validateCitationReviewTransition} from './citation-updates.mjs';
import {eligibilityDigest,eligibilityInput,eligibilityModel,eligibilityPage,eligibilityReport,eligibilityExport,
  recordEligibilityOperation,validateEligibilityState,validateEligibilityTransition} from './eligibility-review.mjs';

const DOCUMENT = 'sf88-research-dossier-v1';
const PORTABLE = 'sf88-research-dossier-portable-v1';
const MAX_RESPONSE = 64 * 1024 * 1024;
const MAX_STATE = 8 * 1024 * 1024;
const MAX_PORTABLE = 256 * 1024 * 1024;
const clone = value => structuredClone(value);
const timestamp = () => new Date().toISOString();
const newId = prefix => prefix + '_' + randomUUID();
const filename = revision => String(revision).padStart(8, '0') + '.json';
const validId = id => typeof id === 'string' && /^d_[a-f0-9-]{36}$/.test(id);
const text = (value, name, max, empty = false) => {
  need(typeof value === 'string' && value.length <= max && (empty || value.trim().length > 0), name);
  return value;
};
const summary = state => ({
  id: state.id, title: state.title, description: state.description, revision: state.revision,
  createdAt: state.createdAt, updatedAt: state.updatedAt,
  questionCount: state.questions.length, editionCount: state.editions.length,
  selectedCount: state.selections.filter(selection => selection.selected).length,
  findingCount: state.findings.length, citationReviewCount:(state.citationReviews??[]).length,
  eligibilityReviewCount:(state.eligibilityEvents??[]).filter(value=>value.action==='create-review').length,
});
const referenceKeys = new Set(['id', 'editionId', 'queryId', 'workspaceId', 'operationId']);
function referenceValue(reference) {
  need(object(reference) && Object.keys(reference).length > 0 &&
    (typeof reference.editionId === 'string' || typeof reference.id === 'string'), 'EDITION_REFERENCE_REQUIRED');
  need(Object.entries(reference).every(([key, value]) => referenceKeys.has(key) &&
    typeof value === 'string' && value.length > 0 && value.length <= 512), 'EDITION_REFERENCE_INVALID');
  return clone(reference);
}

export async function openDossierStore(directory, { providers = {} } = {}) {
  directory = await privateDirectory(directory);
  const projects = await privateDirectory(join(directory, 'dossiers'));
  const blobs = await privateDirectory(join(directory, 'blobs'));
  need(object(providers), 'EDITION_PROVIDERS_INVALID');
  const dossierDirectory = id => {
    need(validId(id), 'DOSSIER_ID_INVALID');
    return join(projects, id);
  };
  async function revisionsDirectory(id, create = false) {
    const parent = await privateDirectory(dossierDirectory(id), { create });
    return privateDirectory(join(parent, 'revisions'), { create });
  }
  async function numbers(id) {
    let entries;
    try { entries = await readdir(await revisionsDirectory(id), { withFileTypes: true }); }
    catch (error) { if (error.code === 'ENOENT') throw new BuyerError('DOSSIER_NOT_FOUND'); throw error; }
    const values = entries.filter(entry => entry.isFile() && /^[0-9]{8}\.json$/.test(entry.name))
      .map(entry => Number(entry.name.slice(0, 8))).sort((a, b) => a - b);
    need(values.every((value, index) => value === index + 1), 'DOSSIER_HISTORY_INCOMPLETE');
    return values;
  }
  function validateEnvelope(envelope, id, revision) {
    need(object(envelope) && object(envelope.state) && typeof envelope.sha256 === 'string', 'DOSSIER_REVISION_INVALID');
    const state = envelope.state;
    need(state.schema === DOCUMENT && state.id === id && state.revision === revision &&
      digest(jsonBytes(state)) === envelope.sha256, 'DOSSIER_REVISION_CHANGED');
    need(Array.isArray(state.questions) && Array.isArray(state.editions) &&
      Array.isArray(state.selections) && Array.isArray(state.findings), 'DOSSIER_STATE_INVALID');
    return envelope;
  }
  async function readRevision(id, revision) {
    need(Number.isSafeInteger(revision) && revision > 0 && revision < 100000000, 'REVISION_INVALID');
    const envelope = await readJson(join(await revisionsDirectory(id), filename(revision)), MAX_STATE);
    return validateEnvelope(envelope, id, revision);
  }
  async function head(id, revision) {
    const all = await numbers(id);
    need(all.length > 0, 'DOSSIER_NOT_FOUND');
    const selected = revision ?? all.at(-1);
    need(all.includes(selected), 'REVISION_NOT_FOUND');
    return readRevision(id, selected);
  }
  async function history(id) {
    const all = await numbers(id);
    const values = [];
    let previous = null;
    for (const revision of all) {
      const envelope = await readRevision(id, revision);
      need(envelope.state.previous === previous, 'DOSSIER_HISTORY_CHANGED');
      values.push(envelope); previous = envelope.sha256;
    }
    return values;
  }
  async function putBlob(bytes) {
    need(Buffer.isBuffer(bytes) && bytes.length <= MAX_RESPONSE, 'RESEARCH_RESPONSE_TOO_LARGE');
    const sha256 = digest(bytes), path = join(blobs, sha256);
    try { await writeBytes(path, bytes, { exclusive: true }); }
    catch (error) {
      if (error.code !== 'EEXIST') throw error;
      need(digest(await readBytes(path, MAX_RESPONSE)) === sha256, 'RESEARCH_BLOB_CHANGED');
    }
    return { sha256, bytes: bytes.length };
  }
  async function blob(metadata) {
    need(object(metadata) && /^[a-f0-9]{64}$/.test(metadata.sha256) &&
      Number.isSafeInteger(metadata.bytes) && metadata.bytes >= 0 && metadata.bytes <= MAX_RESPONSE, 'RESEARCH_BLOB_INVALID');
    const bytes = await readBytes(join(blobs, metadata.sha256), MAX_RESPONSE);
    need(bytes.length === metadata.bytes && digest(bytes) === metadata.sha256, 'RESEARCH_BLOB_CHANGED');
    return bytes;
  }
  /** Open an edition from the selected saved revision through the original verified blob reader. */
  async function readRetainedEdition(id, editionId, {revision} = {}) {
    const {state} = await head(id, revision);
    const edition = state.editions.find(value => value.id === editionId);
    need(edition?.mode === 'retained', 'RETAINED_EDITION_REQUIRED');
    return {edition: clone(edition), revision: state.revision, bytes: await blob(edition.raw)};
  }
  const metadata = state => ({ ...summary(state), schema: DOCUMENT,
    questions: clone(state.questions), editions: clone(state.editions),
    selections: clone(state.selections), findings: clone(state.findings) });
  async function commit(id, expectedRevision, label, update, { projection = 'full' } = {}) {
    need(['full', 'metadata'].includes(projection), 'RESEARCH_PROJECTION_INVALID');
    const current = await head(id);
    need(Number.isSafeInteger(expectedRevision) && current.state.revision === expectedRevision, 'REVISION_CONFLICT');
    const next = clone(current.state);
    const changed = await update(next, current.state);
    if (changed === false) return projection === 'metadata' ? metadata(current.state) : get(id);
    next.revision += 1;
    need(next.revision < 100000000, 'REVISION_LIMIT');
    next.previous = current.sha256; next.updatedAt = timestamp(); next.change = label;
    const envelope = { sha256: digest(jsonBytes(next)), state: next };
    need(jsonBytes(envelope).length <= MAX_STATE, 'DOSSIER_STATE_TOO_LARGE');
    try { await writeJson(join(await revisionsDirectory(id), filename(next.revision)), envelope, { exclusive: true }); }
    catch (error) { if (error.code === 'EEXIST') throw new BuyerError('REVISION_CONFLICT'); throw error; }
    return projection === 'metadata' ? metadata(next) : get(id);
  }
  async function projections(state, { references = true, readContent = blob } = {}) {
    const views = new Map();
    for (const edition of state.editions) {
      if (edition.mode === 'retained') {
        const normalized = normalizeResponse(await readContent(edition.raw), edition.provider);
        views.set(edition.id, normalized);
      } else if (edition.mode === 'reference') {
        let projection = { status: references ? 'ADAPTER_UNAVAILABLE' : 'ORIGINAL_EDITION_REFERENCE', items: [] };
        const adapter = providers[edition.provider];
        if (references && adapter && typeof adapter.read === 'function') {
          try {
            projection = normalizeProjection(await adapter.read(clone(edition.reference)), edition.provider);
            if (projection.availableUntil && Date.parse(projection.availableUntil) <= Date.now()) {
              projection = { ...projection, status: 'EXPIRED', items: [] };
            }
          } catch (error) {
            projection = { status: 'UNAVAILABLE', items: [], error: safeCode(error.code, 'EDITION_READ_FAILED') };
          }
        }
        views.set(edition.id, projection);
      } else throw new BuyerError('EDITION_MODE_INVALID');
    }
    return views;
  }
  async function view(state, { references = true, includeHistory = true } = {}) {
    const projected = await projections(state, { references });
    const sources = sourceView(state.editions, projected, state.selections);
    const occurrenceSource = new Map(sources.flatMap(source => source.occurrenceIds.map(key => [key, source.id])));
    const editions = state.editions.map(edition => {
      const result = projected.get(edition.id);
      return { ...clone(edition), status: result.status, itemCount: result.items.length,
        capturedAt: edition.createdAt, usage: result.usage ?? {},
        warnings: result.warnings ?? [], error: result.error ?? null,
        availableUntil: result.availableUntil ?? null, sourceTerms: result.sourceTerms ?? null };
    });
    const questions = state.questions.map(question => ({
      ...clone(question),
      editionCount: editions.filter(edition => edition.questionId === question.id).length,
      sourceCount: sources.filter(source => source.citations.some(citation => citation.questionId === question.id)).length,
    }));
    const findings = state.findings.map(finding => ({
      ...clone(finding),
      sourceIds: [...new Set(finding.occurrenceIds.map(key => occurrenceSource.get(key)).filter(Boolean))],
      unavailableSources: finding.occurrenceIds.filter(key => !occurrenceSource.has(key)).length,
    }));
    const revisions = includeHistory ? (await history(state.id)).map(envelope => ({
      revision: envelope.state.revision, createdAt: envelope.state.updatedAt,
      label: envelope.state.change, sha256: envelope.sha256,
    })) : [];
    return {
      ...summary(state), schema: DOCUMENT, questions, editions, sources, findings, revisions,
      providerUsage: editions.map(edition => ({ editionId: edition.id, label: edition.label, provider: edition.provider,
        mode: edition.mode, status: edition.status, usage: edition.usage })),
      unavailableSelections: state.selections.filter(selection => !occurrenceSource.has(selection.occurrenceId)),
    };
  }
  async function get(id, { revision, references = true, includeHistory = true } = {}) {
    need(typeof references === 'boolean' && typeof includeHistory === 'boolean', 'RESEARCH_PROJECTION_INVALID');
    return view((await head(id, revision)).state, {references, includeHistory});
  }
  async function listRevisions(id, {revision} = {}) {
    const selected = (await head(id, revision)).state.revision;
    return (await history(id)).filter(envelope => envelope.state.revision <= selected).map(envelope => ({
      revision: envelope.state.revision, createdAt: envelope.state.updatedAt,
      label: envelope.state.change, sha256: envelope.sha256}));
  }
  // Return saved revision metadata without loading or projecting retained response bodies.
  async function getMetadata(id, { revision } = {}) { return metadata((await head(id, revision)).state); }
  async function list() {
    const entries = await readdir(projects, { withFileTypes: true });
    const values = [];
    for (const entry of entries) {
      if (!entry.isDirectory() || !validId(entry.name)) continue;
      try { values.push(summary((await head(entry.name)).state)); }
      catch (error) { if (error.code !== 'DOSSIER_NOT_FOUND') throw error; }
    }
    return values.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
  }
  async function create({ title, description = '', projection = 'full' } = {}) {
    need(['full', 'metadata'].includes(projection), 'RESEARCH_PROJECTION_INVALID');
    title = text(title, 'TITLE_REQUIRED', 240);
    description = text(description, 'DESCRIPTION_INVALID', 20000, true);
    const id = newId('d'), now = timestamp();
    const state = { schema: DOCUMENT, id, title, description, revision: 1,
      previous: null, createdAt: now, updatedAt: now, change: 'Created dossier',
      questions: [], editions: [], selections: [], findings: [], citationReviews: [], eligibilityEvents: [] };
    await writeJson(join(await revisionsDirectory(id, true), filename(1)),
      { sha256: digest(jsonBytes(state)), state }, { exclusive: true });
    return projection === 'metadata' ? getMetadata(id) : get(id);
  }
  const update = (id, { title, description, expectedRevision, projection = 'full' }) => commit(id, expectedRevision, 'Updated dossier', state => {
    if (title !== undefined) state.title = text(title, 'TITLE_REQUIRED', 240);
    if (description !== undefined) state.description = text(description, 'DESCRIPTION_INVALID', 20000, true);
  }, {projection});
  const addQuestion = (id, { text: questionText, expectedRevision, projection = 'full' }) => commit(id, expectedRevision, 'Added research question', state => {
    state.questions.push({ id: newId('q'), text: text(questionText, 'QUESTION_REQUIRED', 4000),
      notes: '', status: 'open', createdAt: timestamp() });
  }, {projection});
  const updateQuestion = (id, questionId, { text: questionText, notes, status, expectedRevision, projection = 'full' }) =>
    commit(id, expectedRevision, 'Updated research question', state => {
      const question = state.questions.find(row => row.id === questionId);
      need(question, 'QUESTION_NOT_FOUND');
