  // delivery therefore refers to the same immutable dossier and source.
  const result=await client.exportEligibility(dossierId,{...options,format,section});
  need(result?.revision===options.revision&&hash(result.sha256)&&integer(result.bytes)&&
    typeof result.file==='string','ELIGIBILITY_EXPORT_RECEIPT_CHANGED');
  return result;
}

// MIT. Question-scoped eligibility reviews beside the original Research dossier.
// Reviewers are named local-workspace operators. Original retained editions and
// the immutable dossier history remain the source and receiving boundary.
import {digest,jsonBytes,need,object} from '../node/store.mjs';
